<template>
  <Header />
  <main class="mx-auto w-full min-w-0 max-w-7xl space-y-6 px-4 pb-16 pt-28 sm:px-8 sm:pt-36">
    <section class="rounded-3xl bg-gradient-to-br from-slate-950 to-blue-950 p-6 text-white sm:p-9"><p class="text-xs font-bold uppercase tracking-[.2em] text-blue-300">NBA · командная статистика</p><div class="mt-3 flex flex-wrap items-end justify-between gap-4"><div><RouterLink v-if="isDetail" :to="catalogLocation" class="mb-3 inline-block text-sm font-bold text-blue-200 hover:text-white">← Все показатели</RouterLink><h1 class="text-3xl font-black sm:text-5xl">{{ isDetail ? selectedMetric?.label || 'Показатель команд' : 'Чарт команд' }}</h1><p class="mt-3 text-sm text-blue-100">Лидеры лиги по результативности, броскам, подборам и другим показателям</p></div><label class="text-xs font-bold text-blue-200">Сезон<select v-model.number="season" aria-label="Сезон чарта" class="mt-2 block rounded-xl bg-white p-3 text-sm text-slate-900"><option v-for="year in seasons" :key="year" :value="year">{{ year-1 }}–{{ String(year).slice(-2) }}</option></select></label></div></section>
    <div role="tablist" aria-label="Этап сезона" class="flex gap-2 rounded-2xl border border-slate-200 bg-white p-2"><button v-for="stage in stages" :id="`chart-tab-${stage.id}`" :key="stage.id" role="tab" type="button" :aria-selected="type===stage.id" aria-controls="chart-content" :tabindex="type===stage.id?0:-1" class="flex-1 rounded-xl px-3 py-3 text-sm font-bold transition" :class="type===stage.id?'bg-blue-600 text-white shadow-sm':'text-slate-500 hover:bg-slate-50'" @click="type=stage.id" @keydown.left.prevent="type=2" @keydown.right.prevent="type=3">{{ stage.label }}</button></div>
    <section id="chart-content" role="tabpanel" :aria-labelledby="`chart-tab-${type}`" class="space-y-6">
      <p v-if="query.isPending.value" role="status" class="rounded-2xl bg-white p-10 text-center text-slate-500">Собираем статистику команд…</p>
      <p v-if="query.error.value" role="alert" class="rounded-xl bg-rose-50 p-4 text-sm text-rose-700">{{ query.error.value.message }} <button class="font-bold underline" @click="query.refetch()">Повторить</button></p>
      <p v-if="data&&!data.complete" class="rounded-xl bg-amber-50 p-4 text-sm leading-6 text-amber-800">Часть статистики пока не опубликована или недоступна. Места появятся после получения полного набора команд. <button class="font-bold underline" @click="query.refetch()">Обновить</button></p>
      <template v-if="data && played.length">
        <section v-if="isDetail && selectedMetric" class="scroll-mt-28 overflow-hidden rounded-3xl border border-slate-200 bg-white">
          <div class="flex flex-wrap items-start justify-between gap-3 border-b border-slate-100 p-5"><div><p class="text-xs font-bold uppercase tracking-wider text-blue-600">Рейтинг команд</p><h2 class="mt-1 text-xl font-black text-slate-900">{{ selectedMetric?.label }}</h2><p class="mt-2 text-xs text-slate-500">{{ selectedMetric?.direction==='asc'?'Меньше — выше место':'Больше — выше место' }} · команды с матчами выбранного этапа</p></div><div class="flex w-full flex-wrap items-center gap-3 sm:w-auto"><select :value="selectedMetric?.key" @change="changeMetric" aria-label="Показатель рейтинга" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-700 sm:w-72"><option v-for="metric in metrics" :key="metric.key" :value="metric.key">{{ metric.label }}</option></select><span class="rounded-full bg-slate-50 px-3 py-2 text-xs font-bold text-slate-500">{{ ranked.length }} команд</span></div></div>
          <div class="overflow-x-auto"><table class="w-full min-w-[300px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-3 py-3 sm:px-5">Место</th><th class="px-3 py-3">Команда</th><th class="px-3 py-3 text-center">Игр</th><th class="px-3 py-3 text-right sm:px-5">{{ selectedMetric?.percent?'%':'Значение' }}</th></tr></thead><tbody><tr v-for="(team,i) in ranked" :key="team.id" class="border-t border-slate-100"><td class="w-14 px-3 py-3 font-black sm:px-5" :class="i<3?'text-amber-500':'text-slate-400'">{{ team.ranks[selectedMetric!.key]?.place ?? '—' }}</td><td class="px-3 py-3"><RouterLink :to="`/team/${team.abbr}`" class="flex items-center gap-3 font-bold text-slate-800 hover:text-blue-600"><img :src="`/logos/${team.abbr}.svg`" alt="" class="h-8 w-8 shrink-0 object-contain"/><span class="hidden sm:inline">{{ team.name }}</span><span class="sm:hidden">{{ team.abbr }}</span></RouterLink></td><td class="px-3 py-3 text-center text-slate-400">{{ team.gamesPlayed }}</td><td class="px-3 py-3 text-right font-black text-slate-900 sm:px-5">{{ value(team.stats[selectedMetric!.key],selectedMetric) }}</td></tr></tbody></table></div>
        </section>
        <p v-if="isDetail&&!selectedMetric" role="alert" class="rounded-2xl bg-white p-8 text-slate-600">Показатель не найден. Выберите его в <RouterLink :to="catalogLocation" class="text-blue-600 underline">каталоге чарта</RouterLink>.</p><section v-if="!isDetail" class="space-y-4"><div class="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h2 class="text-xl font-black text-slate-900">Все показатели</h2><p class="mt-1 text-xs text-slate-500">Выберите показатель, чтобы открыть полный рейтинг</p></div><input v-model="search" aria-label="Найти командный показатель" type="search" placeholder="Очки, подборы, трёхочковые…" class="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm sm:w-72" /></div><div class="flex flex-wrap gap-2"><button v-for="group in groups" :key="group.id" class="rounded-full px-4 py-2 text-xs font-bold" :class="category===group.id?'bg-slate-900 text-white':'bg-white text-slate-500 ring-1 ring-slate-200'" @click="category=group.id">{{ group.label }}</button></div>
          <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><RouterLink v-for="metric in filteredMetrics" :key="metric.key" :to="metricLocation(metric.key)" class="rounded-2xl border border-slate-200 bg-white p-5 text-left transition hover:border-blue-300 hover:shadow-sm"><p class="text-sm font-bold text-slate-900">{{ metric.label }}</p><div v-if="leader(metric)" class="mt-4 flex items-center gap-3"><img :src="`/logos/${leader(metric)!.abbr}.svg`" alt="" class="h-10 w-10 object-contain"/><div class="min-w-0 flex-1"><p class="truncate text-xs font-bold text-slate-600">{{ leader(metric)!.name }}</p><p class="mt-1 text-[10px] text-slate-400">{{ data.complete?'Лидер показателя':'Предварительное значение' }} · {{ metric.direction==='asc'?'меньше — выше':'больше — выше' }}</p></div><strong class="text-xl text-blue-600">{{ value(leader(metric)!.stats[metric.key],metric) }}</strong></div></RouterLink></div><p v-if="!filteredMetrics.length" class="rounded-2xl bg-white p-8 text-center text-sm text-slate-500">Показатели не найдены. Измените поиск или категорию.</p>
        </section>
        <p class="text-xs leading-5 text-slate-400">Суммарные и средние показатели разделены. Равные точные значения делят место; отображение округляется. Проценты бросков ранжируются только при наличии попыток. eFG% учитывает дополнительную ценность трёхочковых; TS% также учитывает штрафные (коэффициент 0,44). Данные ESPN · обновлено {{ updated }} МСК.</p>
      </template>
      <p v-else-if="data&&!query.isPending.value" class="rounded-3xl bg-white p-10 text-center text-sm leading-6 text-slate-500">Для этого этапа сезона командная статистика пока не опубликована.<br>Выберите другой сезон или этап.</p>
    </section>
  </main>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQuery} from '@tanstack/vue-query'
import Header from '../components/Headers/Header.vue'
import {usePageTitle} from '../composables/usePageTitle'
type Metric={key:string;label:string;group:string;percent:boolean;direction:'asc'|'desc'}
type Team={id:string;abbr:string;name:string;gamesPlayed:number;stats:Record<string,number>;ranks:Record<string,{place:number;total:number}|null>}
type Data={complete:boolean;metrics:Metric[];teams:Team[];updatedAt:string}
const route=useRoute(),router=useRouter(),now=new Date(),currentYear=now.getUTCFullYear()+(now.getUTCMonth()>=6?1:0),seasons=Array.from({length:currentYear-2015},(_,i)=>currentYear-i)
const requested=Number(route.query.season),season=ref(seasons.includes(requested)?requested:currentYear),type=ref(Number(route.query.type)===3?3:2),search=ref(''),category=ref('all')
const stages=[{id:2,label:'Регулярный чемпионат'},{id:3,label:'Плей-офф'}],groups=[{id:'all',label:'Все'},{id:'offensive',label:'Атака'},{id:'defensive',label:'Защита'},{id:'general',label:'Общие'},{id:'efficiency',label:'Точность и эффективность'},{id:'totals',label:'Суммарные'}]
const query=useQuery({queryKey:computed(()=>['team-chart',season.value,type.value]),queryFn:async({signal,queryKey})=>{const r=await fetch(`/api/team-chart?season=${queryKey[1]}&type=${queryKey[2]}`,{signal:AbortSignal.any([signal,AbortSignal.timeout(30000)])});const d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось загрузить чарт');return d as Data},staleTime:60000,retry:1})
const data=query.data,played=computed(()=>data.value?.teams.filter(t=>t.gamesPlayed>0)||[])
const priority=['avgPoints','avgRebounds','avgAssists','avgThreePointFieldGoalsMade','fieldGoalPct','threePointPct','avgSteals','avgBlocks']
const metrics=computed(()=>[...(data.value?.metrics||[])].sort((a,b)=>{const x=priority.indexOf(a.key),y=priority.indexOf(b.key);return (x<0?100:x)-(y<0?100:y)||a.label.localeCompare(b.label,'ru')}))
const isDetail=computed(()=>typeof route.params.metric==='string'&&route.params.metric.length>0),selectedMetric=computed(()=>metrics.value.find(m=>m.key===route.params.metric))
const catalogLocation=computed(()=>({path:'/chart',query:{season:String(season.value),type:String(type.value)}}))
const metricLocation=(key:string)=>({path:`/chart/${encodeURIComponent(key)}`,query:{season:String(season.value),type:String(type.value)}})
function changeMetric(event:Event){void router.push(metricLocation((event.target as HTMLSelectElement).value))}
function order(m:Metric){return played.value.filter(t=>Number.isFinite(t.stats[m.key])&&(data.value?.complete?t.ranks[m.key]!==null:true)).sort((a,b)=>(m.direction==='asc'?1:-1)*(a.stats[m.key]!-b.stats[m.key]!)||a.name.localeCompare(b.name))}
const ranked=computed(()=>selectedMetric.value?order(selectedMetric.value):[]),filteredMetrics=computed(()=>metrics.value.filter(m=>(category.value==='all'||m.group===category.value)&&m.label.toLowerCase().includes(search.value.toLowerCase().trim())))
const leader=(m:Metric)=>order(m)[0]
const value=(n:number|undefined,m:Metric|undefined)=>n===undefined?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n)+(m?.percent?'%':'')
const updated=computed(()=>data.value?new Date(data.value.updatedAt).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}):'—')
watch([season,type],()=>{void router.replace({query:{season:String(season.value),type:String(type.value)}})})
watch(()=>[route.query.season,route.query.type],()=>{const year=Number(route.query.season);season.value=seasons.includes(year)?year:currentYear;type.value=Number(route.query.type)===3?3:2})
usePageTitle(()=>isDetail.value?`${selectedMetric.value?.label||'Показатель'} — Чарт команд НБА`:'Чарт команд НБА')
</script>
